types.definition:
enum option-type {
    boolean,
    integer,
    string,
}

record schema-field {
    name: string,
    schema: u32,
    required: bool,
    doc: string,
}

variant schema-node {
    scalar(option-type),
    enum-of(list<string>),
    list-of(u32),
    record(list<schema-field>),
}

record config-schema {
    nodes: list<schema-node>,
    root: u32,
}

record config-value {
    nodes: list<value-node>,
    root: u32,
}

record config-diagnostic {
    message: string,
    source: string,
}

record ctx {
    pane-width: u32,
    nerd-fonts: bool,
    version: string,
}

enum align {
    left,
    center,
}

variant link-target {
    command(string),
    topic(string),
    url(string),
}

record span {
    text: string,
    role: role,
    link: option<link-target>,
}

record row {
    spans: list<span>,
    align: align,
}

record fragment {
    rows: list<row>,
}

enum severity {
    error,
    warning,
    info,
    note,
}

record source-location {
    path: string,
    line: u32,
    buffer: u32,
}

record conceal-rule {
    pattern: string,
    hide: list<u32>,
    slot: option<string>,
}

enum mode-kind {
    major,
    minor,
}

types.doc:
Which buffers a mode auto-activates on — mirrors `ActivationPolicy`.
`manual` = only on explicit activation; `global` = document buffers only;
`universal` = every buffer; `majors` = an allowlist of major-mode ids.

types.definition:
variant activation-policy {
    manual,
    global,
    universal,
    majors(list<string>),
}

record mode-keymap-binding {
    binding-mode: binding-mode,
    chord: string,
    command: string,
}

enum override-priority {
    low,
    normal,
    high,
}

record mode-option-override {
    name: string,
    value: string,
    priority: override-priority,
}

record candidate-pair {
    candidate: raw-candidate,
    routing: routing-payload,
}

record git-source {
    url: string,
    rev: option<string>,
}

variant plugin-source {
    local(string),
    git(git-source),
    prebuilt(string),
}

record plugin-spec {
    name: string,
    source: plugin-source,
    enable-mode: option<string>,
    pinned: bool,
}

enum project-kind {
    marker,
    pwd,
}

record project-info {
    root: string,
    kind: project-kind,
    marker: string,
}

record annotation {
    text: string,
    spans: list<display-span>,
}

record entry {
    line: u32,
    end-line: u32,
    group: string,
    label: string,
    sort-key: s64,
    spans: list<display-span>,
    annotation: option<annotation>,
    emphasis: bool,
}

record clock-span {
    line: u32,
    outline: list<string>,
    day: s64,
    minutes: u32,
}

record scan-result {
    entries: list<entry>,
    clock: list<clock-span>,
}

variant color-ref {
    palette(string),
    literal-rgb(u32),
    default,
}

record capture {
    name: string,
    node: node,
}

record capture-range {
    name: string,
    match-index: u32,
    range: range,
}

record candidate-file {
    path: string,
    is-dir: bool,
    size: option<u64>,
}

record candidate-option {
    name: string,
    current-value: string,
    doc: string,
}

record candidate-option-value {
    option-name: string,
    value: string,
    doc: string,
}

record candidate-chord {
    chord: string,
    mode-label: string,
    doc: string,
}

record candidate-register {
    name: char,
    preview: string,
}

record candidate-mark {
    name: char,
    position: string,
}

record candidate-extension {
    kind-id: u32,
    payload: list<u8>,
}

variant key-kind {
    char(char),
    special(special-key),
}

record key-chord {
    key: key-kind,
    mods: u8,
}

record annotation-segment {
    text: string,
    slot: string,
}

record annotation-custom {
    text: string,
    slot: string,
}

record annotation-styled {
    category: string,
    segments: list<annotation-segment>,
}

record display-span {
    start: u32,
    end: u32,
    slot: string,
}

record jump-target {
    buffer-id: u32,
    line: u32,
    col: u32,
}

record location {
    path: string,
    line: u32,
    col: u32,
}

record command-ref {
    id: string,
    args: args,
}

record lsp-code-action-ref {
    handle: u64,
    index: u32,
}

record position {
    line: u32,
    byte: u32,
}

record range {
    start: position,
    end: position,
}

variant edit-kind {
    replace(string),
}

record edit {
    range: range,
    kind: edit-kind,
}

variant visual-mode {
    charwise,
    linewise,
    blockwise,
}

record selection {
    anchor: position,
    head: position,
    visual: option<visual-mode>,
}

record selection-set {
    selections: list<selection>,
    primary: u32,
}

variant visual-kind {
    charwise,
    linewise,
    blockwise,
}

variant search-direction {
    forward,
    backward,
}

variant yank-kind {
    charwise,
    linewise,
    blockwise,
}

variant quit-scope {
    pane,
    all,
}

variant substitute-scope {
    current-line,
    whole,
}

record utf16-pos {
    line: u32,
    col: u32,
}

enum popup-placement {
    centered,
    cursor-anchored,
    minibuffer-band,
}

enum popup-focus {
    steal,
    passive,
}

record open-popup-payload {
    name: string,
    mode-id: string,
    placement: popup-placement,
    focus: popup-focus,
}

record confirm-payload {
    prompt: string,
    yes-action: string,
    args: args,
}

record open-transient-payload {
    source: string,
    args: args,
}

record open-prompt-payload {
    prompt: string,
    initial: string,
    on-submit-action: string,
    buffer-name: option<string>,
}

variant file-anchor {
    end,
    start,
    line(u32),
}

record apply-edit-payload {
    target: u32,
    edit: edit,
    cursor: option<position>,
}

record yank-payload {
    register: register,
    content: string,
    kind: yank-kind,
    explicit-yank: bool,
}

record quit-payload {
    force: bool,
    scope: quit-scope,
}

record open-buffer-payload {
    path: option<string>,
    force: bool,
}

record open-buffer-at-column-payload {
    path: option<string>,
    column: option<utf16-pos>,
    force: bool,
}

record spawn-terminal-payload {
    cwd: option<string>,
    cmd-line: option<string>,
    env: list<tuple<string, string>>,
    activate-minor: option<string>,
}

record echo-payload {
    level: echo-level,
    text: string,
}

record substitute-payload {
    scope: substitute-scope,
    pattern: string,
    replacement: string,
    global: bool,
}

record describe-command-payload {
    name: string,
    anchor: option<string>,
}

record set-lsp-log-level-payload {
    server-id: option<string>,
    level: string,
}

record diffsplit-payload {
    path: string,
    remote: option<string>,
}

record close-session-diffs-payload {
    origin-session: u64,
    tab-name: string,
}

variant viewport-pos {
    top,
    middle,
    bottom,
}

variant scroll-pos {
    top,
    center,
    bottom,
}

variant pane-direction {
    left,
    down,
    up,
    right,
}

variant hscroll {
    columns(bool),
    half-screen(bool),
    cursor-to-edge(bool),
}

record narrow-lines-payload {
    start-line: u32,
    end-line: u32,
}

enum format-intent {
    indent,
    reflow,
    reformat,
}

record format-range-payload {
    intent: format-intent,
    start-line: u32,
    end-line: u32,
}

record open-provider-view-payload {
    provider: string,
    argument: option<string>,
    scan-args: list<string>,
}

record multibuffer-view-excerpt {
    path: string,
    start-line: u32,
    end-line: u32,
    header: string,
    match-count: option<u32>,
}

variant multibuffer-view-input {
    pull,
    scan,
}

record multibuffer-view-result {
    excerpts: list<multibuffer-view-excerpt>,
    summary: string,
}

record generate-context {
    prefix: string,
    case-sensitive: bool,
    line-before-cursor: string,
    language: string,
}

record completion-source-spec {
    id: string,
    doc: string,
    accepts-non-word-query: bool,
}

variant open-target {
    default,
    split,
    vsplit,
    tab,
}

types.doc:
Payload records for the multi-field `routing-payload` arms. `lsp-location`
and `jump-in-buffer` reuse the shared `location` / `jump-target` records;
`invoke-command` reuses `command-ref`.

types.definition:
record resolve-diff-payload {
    primary: u32,
    accept: bool,
}

record lsp-instance-payload {
    server-id: string,
    workspace: string,
}

record show-message-action-payload {
    request-id: u32,
    action-index: u32,
}

record ai-session-payload {
    provider: string,
    index: u32,
}

variant position-source {
    auto-jump,
    explicit-mark,
    plugin-push,
    named-mark(char),
}

record position-entry {
    buffer-id: u32,
    line: u32,
    col: u32,
    source: position-source,
}

record symbol-location {
    name: string,
    line: u32,
    col: u32,
}

record transient-context {
    major-mode: option<string>,
    minor-modes: list<string>,
    buffer: option<u32>,
    args: args,
}

record transient-action {
    command: string,
    args: args,
}

record transient-argument {
    name: string,
    default: option<string>,
    prompt: string,
}

variant transient-item-kind {
    action(transient-action),
    argument(transient-argument),
    dismiss,
}

record transient-item {
    key: list<string>,
    label: string,
    description: string,
    kind: transient-item-kind,
}

record transient-group {
    label: string,
    items: list<transient-item>,
}

record transient-spec {
    title: string,
    groups: list<transient-group>,
    footer: option<string>,
}

enum latency-class {
    reflex,
    display,
    background,
}

variant surface-form {
    keyword,
    delimiter(string),
}

record motion-context {
    buffer-id: u32,
    from: position,
    count: count,
    has-explicit-count: bool,
    args: args,
}

record motion-result {
    target: position,
    linewise: bool,
}

record text-object-context {
    at: position,
    count: count,
    args: args,
}

record motion-spec {
    jump: bool,
    exclusive: bool,
    args-schema: list<arg-spec>,
}

record text-object-spec {
    args-schema: list<arg-spec>,
}

record action-spec {
    args-schema: list<arg-spec>,
}

record event-applied-edit {
    original-range: range,
    inserted-range: range,
    replaced-text: string,
    inserted-text: string,
}

record event-filter {
    kinds: option<list<event-kind>>,
    path-globs: option<list<string>>,
    major-modes: option<list<string>>,
    minor-modes: option<list<string>>,
}

record event-plugin-lifecycle {
    name: string,
    id: u32,
}

record event-document-opened {
    id: u64,
    path: option<string>,
    version: u64,
    text: string,
}

record event-document-path {
    id: u64,
    path: string,
}

record event-document-changed {
    id: u64,
    path: option<string>,
    version: u64,
    edits: list<event-applied-edit>,
}

record event-selections-changed {
    id: u64,
    version: u64,
    selections: selection-set,
}

record event-modal-mode-changed {
    from-state: string,
    to-state: string,
}

record event-option-changed {
    name: string,
    old: option<string>,
    new-value: string,
}

record event-mode-lifecycle {
    buffer: u64,
    mode: string,
}

record event-plugin {
    name: string,
    payload: list<u8>,
}

enum gutter-diff-kind {
    add,
    remove,
    change,
    conflict,
}

enum gutter-severity-level {
    hint,
    info,
    warning,
    error,
}

record gutter-diff {
    line: u32,
    kind: gutter-diff-kind,
}

record gutter-severity {
    line: u32,
    level: gutter-severity-level,
}

record gutter-sign {
    line: u32,
    name: string,
}

variant gutter-decoration {
    diff(gutter-diff),
    severity(gutter-severity),
    sign(gutter-sign),
}

record decoration-context {
    buffer-id: u64,
    path: option<string>,
    line-count: u32,
}

enum media-fit {
    contain,
    width,
}

record media-block {
    anchor-line: u32,
    path: string,
    alt: option<string>,
    fit: media-fit,
}

record context-scope {
    scope-start: u32,
    scope-end: u32,
    header-start: u32,
    header-end: u32,
}

record context-request {
    buffer-id: u64,
    path: option<string>,
    line-count: u32,
}

enum ui-zone {
    left,
    center,
    right,
}

record ui-notification {
    level: echo-level,
    message: string,
}
